public class SoftPanel : Panel {
 public Color BorderColor=Color.FromArgb(225,230,240);
 public SoftPanel(){DoubleBuffered=true;ResizeRedraw=true;}
 public static GraphicsPath Outline(RectangleF r,float radius){var p=new GraphicsPath();float d=Math.Min(radius*2,Math.Min(r.Width,r.Height));p.AddArc(r.X,r.Y,d,d,180,90);p.AddArc(r.Right-d,r.Y,d,d,270,90);p.AddArc(r.Right-d,r.Bottom-d,d,d,0,90);p.AddArc(r.X,r.Bottom-d,d,d,90,90);p.CloseFigure();return p;}
 protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);e.Graphics.SmoothingMode=SmoothingMode.AntiAlias;float scale=e.Graphics.DpiX/96f;float inset=Math.Max(1,scale);using(var p=Outline(new RectangleF(inset,inset,Width-2*inset-1,Height-2*inset-1),10*scale))using(var pen=new Pen(ContainsFocus?Color.FromArgb(125,132,198):BorderColor,Math.Max(1,scale)))e.Graphics.DrawPath(pen,p);}
}
