public static class HistoryStorage {
 public static List<ClipEntry> Load(string path){foreach(string candidate in new[]{path,path+".tmp",path+".bak"})try{using(var stream=File.OpenRead(candidate)){var items=(List<ClipEntry>)new XmlSerializer(typeof(List<ClipEntry>)).Deserialize(stream);if(items!=null)return items;}}catch{}return new List<ClipEntry>();}
 public static void Save(string path,List<ClipEntry> items){string temp=path+".tmp";using(var stream=new FileStream(temp,FileMode.Create,FileAccess.Write,FileShare.None)){new XmlSerializer(typeof(List<ClipEntry>)).Serialize(stream,items);stream.Flush(true);}if(File.Exists(path)){bool valid=false;try{using(var old=File.OpenRead(path)){new XmlSerializer(typeof(List<ClipEntry>)).Deserialize(old);valid=true;}}catch{}File.Replace(temp,path,valid?path+".bak":null);}else File.Move(temp,path);}
}

