public static class DataMigration {
 public static string Resolve(){string local=Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData);string destination=Path.Combine(local,"Ltools");Migrate(Path.Combine(local,"LilyTools"),destination);return destination;}
 public static void Migrate(string legacy,string destination){Directory.CreateDirectory(destination);if(File.Exists(Path.Combine(destination,"history.xml"))||!File.Exists(Path.Combine(legacy,"history.xml")))return;var items=HistoryStorage.Load(Path.Combine(legacy,"history.xml"));foreach(var item in items){if(item.ImagePath==null)continue;try{string path=Path.GetFullPath(item.ImagePath);if(!string.Equals(Path.GetDirectoryName(path),Path.GetFullPath(legacy),StringComparison.OrdinalIgnoreCase)||!File.Exists(path))continue;string target=Path.Combine(destination,Path.GetFileName(path));File.Copy(path,target,true);item.ImagePath=target;}catch{}}HistoryStorage.Save(Path.Combine(destination,"history.xml"),items);foreach(string name in new[]{"search-state.xml","folders.txt"}){string old=Path.Combine(legacy,name),target=Path.Combine(destination,name);if(File.Exists(old)&&!File.Exists(target))File.Copy(old,target);}}
}
public sealed class ResultIconCache : IDisposable {
 [StructLayout(LayoutKind.Sequential,CharSet=CharSet.Unicode)] struct SHFILEINFO {public IntPtr Icon;public int Index;public uint Attributes;[MarshalAs(UnmanagedType.ByValTStr,SizeConst=260)] public string DisplayName;[MarshalAs(UnmanagedType.ByValTStr,SizeConst=80)] public string TypeName;}
 [DllImport("shell32.dll",CharSet=CharSet.Unicode)] static extern IntPtr SHGetFileInfo(string path,uint attrs,out SHFILEINFO info,uint size,uint flags);
 [DllImport("user32.dll")] static extern bool DestroyIcon(IntPtr icon);
 readonly Dictionary<string,Icon> cache=new Dictionary<string,Icon>(StringComparer.OrdinalIgnoreCase);
 public Icon Get(string path){if(string.IsNullOrEmpty(path))return null;try{path=Path.GetFullPath(path);}catch{return null;}Icon icon;if(cache.TryGetValue(path,out icon))return icon;SHFILEINFO info;bool exists=File.Exists(path)||Directory.Exists(path);IntPtr result=SHGetFileInfo(path,0x80,out info,(uint)Marshal.SizeOf(typeof(SHFILEINFO)),0x100u|(exists?0u:0x10u));if(result==IntPtr.Zero||info.Icon==IntPtr.Zero)return null;try{using(var borrowed=Icon.FromHandle(info.Icon))icon=(Icon)borrowed.Clone();}finally{DestroyIcon(info.Icon);}if(cache.Count>=256){foreach(var entry in cache.Values)entry.Dispose();cache.Clear();}cache[path]=icon;return icon;}
 public void Dispose(){foreach(var icon in cache.Values)icon.Dispose();cache.Clear();}
}
