public static class Recognition {
 public static string LocalPath(string text){string value=(text??"").Trim().Trim('"');Uri uri;if(value.StartsWith("file:",StringComparison.OrdinalIgnoreCase)&&Uri.TryCreate(value,UriKind.Absolute,out uri)&&uri.IsFile)value=Uri.UnescapeDataString(uri.LocalPath);if(Regex.IsMatch(value,@"^/[A-Za-z]:[/\\]"))value=value.Substring(1);if(Regex.IsMatch(value,@"^[A-Za-z]:[/\\]")||value.StartsWith(@"\\"))return value.Replace('/',Path.DirectorySeparatorChar);return value;}
 public static string TypeOf(string text){if(string.IsNullOrWhiteSpace(text))return "空";Uri u;if(Uri.TryCreate(text.Trim(),UriKind.Absolute,out u)&&(u.Scheme=="https"||u.Scheme=="http"))return "网址";if(File.Exists(LocalPath(text))||Directory.Exists(LocalPath(text)))return "路径";if(Regex.IsMatch(text.Trim(),@"^[^\s@]+@[^\s@]+\.[^\s@]+$"))return "邮箱";if(Regex.IsMatch(text.Trim(),@"^[\d\s.+*/()%\-]+$")&&Regex.IsMatch(text,@"\d")&&Regex.IsMatch(text,@"[+*/%\-]"))return "算式";if((text.Trim().StartsWith("{")&&text.Trim().EndsWith("}"))||(text.Trim().StartsWith("[")&&text.Trim().EndsWith("]")))return "JSON 文本";return "文本";}
 public static bool Matches(string text,string query){return query.Split(new[]{' '},StringSplitOptions.RemoveEmptyEntries).All(x=>text.IndexOf(x,StringComparison.CurrentCultureIgnoreCase)>=0);}
 public static string Calculate(string text){if(TypeOf(text)!="算式")throw new Exception("请输入数字与 + - * / % ()");var v=new System.Data.DataTable().Compute(text,"");return Convert.ToString(v,System.Globalization.CultureInfo.InvariantCulture);}
}
