 void RememberSearch(){searchState.Mode=mode;var entry=searchState.Queries.FirstOrDefault(x=>x.Mode==mode);if(entry==null){entry=new SearchQuery{Mode=mode};searchState.Queries.Add(entry);}entry.Query=query.Text;try{string path=Path.Combine(data,"search-state.xml"),temp=path+".tmp";using(var f=File.Create(temp))new XmlSerializer(typeof(SearchState)).Serialize(f,searchState);if(File.Exists(path))File.Replace(temp,path,null);else File.Move(temp,path);}catch{}}
 void ChangeMode(string value){RememberSearch();mode=value;StyleTabs();RememberSearch();RefreshResults();}
 void StyleTabs(){childTag.Visible=mode!="全部";childTag.Text=mode+"  ×";foreach(Button b in tabs.Controls){b.BackColor=(string)b.Tag==mode?accent:Color.FromArgb(241,243,248);b.ForeColor=(string)b.Tag==mode?Color.White:ink;}}
 void StartIndex(){if(indexing)return;indexing=true;RefreshResults();System.Threading.ThreadPool.QueueUserWorkItem(delegate{var items=new List<IndexedItem>();var seen=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(var root in new[]{Environment.GetFolderPath(Environment.SpecialFolder.StartMenu),Environment.GetFolderPath(Environment.SpecialFolder.CommonStartMenu)})Scan(root,items,seen,true,0);var roots=new List<string>{Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory),Environment.GetFolderPath(Environment.SpecialFolder.CommonDesktopDirectory),Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments),Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),"Downloads")};try{roots.AddRange(File.ReadAllLines(Path.Combine(data,"folders.txt")).Where(Directory.Exists));}catch{}foreach(var root in roots)Scan(root,items,seen,false,0);if(!IsDisposed)try{BeginInvoke((Action)(()=>{index=items.OrderBy(x=>x.Name).ToList();indexing=false;RefreshResults();}));}catch{}});}
 static void Scan(string root,List<IndexedItem> items,HashSet<string> seen,bool onlyApps,int depth){if(depth>8||items.Count>=15000||!Directory.Exists(root))return;try{foreach(string f in Directory.GetFiles(root)){if(items.Count>=15000)break;if(!seen.Add(f))continue;string ext=Path.GetExtension(f).ToLowerInvariant();bool app=ext==".lnk"||ext==".exe"||ext==".appref-ms";if(!onlyApps||app)items.Add(new IndexedItem{Name=Path.GetFileNameWithoutExtension(f),Path=f,App=app});}foreach(string d in Directory.GetDirectories(root)){string n=Path.GetFileName(d);if(n=="node_modules"||n==".git"||(File.GetAttributes(d)&FileAttributes.ReparsePoint)!=0)continue;Scan(d,items,seen,onlyApps,depth+1);}}catch{}}
 void AddFolder(){modal=true;try{using(var dialog=new FolderBrowserDialog {Description="选择要加入文件搜索的目录"})if(dialog.ShowDialog(this)==DialogResult.OK){File.AppendAllLines(Path.Combine(data,"folders.txt"),new[]{dialog.SelectedPath});StartIndex();}}finally{modal=false;}}
 ClipEntry ReadClipboard(bool storeImage){try{if(Clipboard.ContainsFileDropList())return new ClipEntry{Files=Clipboard.GetFileDropList().Cast<string>().ToArray(),Created=DateTime.Now};if(Clipboard.ContainsImage()){if(!storeImage)return new ClipEntry{ImagePath="@current",Created=DateTime.Now};string path=Path.Combine(data,Guid.NewGuid()+".png");using(var img=Clipboard.GetImage()){if(img==null)return null;img.Save(path,System.Drawing.Imaging.ImageFormat.Png);}return new ClipEntry{ImagePath=path,Created=DateTime.Now};}if(Clipboard.ContainsText()){var text=Clipboard.GetText();if(!string.IsNullOrEmpty(text)&&text.Length<=200000)return new ClipEntry{Text=text,Created=DateTime.Now};}}catch{}return null;}
 void CaptureClip(){var c=ReadClipboard(true);if(c==null)return;if(c.Text!=null)clips.RemoveAll(x=>x.Text==c.Text);if(c.Files!=null)clips.RemoveAll(x=>x.Files!=null&&x.Files.SequenceEqual(c.Files));clips.Insert(0,c);while(clips.Count>100){DeleteImage(clips[clips.Count-1]);clips.RemoveAt(clips.Count-1);}current=c;pendingClipboardQuery=true;Save();if(Visible){pendingClipboardQuery=false;query.Text=c.Text??"";RefreshResults();query.SelectAll();}}
 void Save(){try{HistoryStorage.Save(History,clips);}catch{tray.Text="Ltools · 历史保存失败，请检查数据目录";}}
 bool RestoreClipboardIfEmpty(){try{var existing=Clipboard.GetDataObject();if(existing!=null&&existing.GetFormats().Length>0)return false;var recent=clips.FirstOrDefault(c=>c.Text!=null||(c.ImagePath!=null&&File.Exists(c.ImagePath))||(c.Files!=null&&c.Files.All(p=>File.Exists(p)||Directory.Exists(p))));if(recent==null)return false;PutClipboard(recent);clipboardRelease.Start();current=recent;return true;}catch{ignoreClip=false;return false;}}
 void DeleteImage(ClipEntry c){if(c.ImagePath==null)return;try{string path=Path.GetFullPath(c.ImagePath);if(string.Equals(Path.GetDirectoryName(path),data,StringComparison.OrdinalIgnoreCase)&&Path.GetExtension(path)==".png")File.Delete(path);}catch{}}
 void ClearHistory(){modal=true;try{if(MessageBox.Show("清空全部本地剪贴板历史？","Ltools",MessageBoxButtons.YesNo)==DialogResult.Yes){ClearPreviewImage();foreach(var c in clips)DeleteImage(c);clips.Clear();Save();RefreshResults();}}finally{modal=false;}}
 void Add(List<Result> rows,string title,string detail,string tag,Action run,ClipEntry c=null){rows.Add(new Result{Title=title,Detail=detail,Tag=tag,Run=run,Clip=c,IconPath=c!=null?(c.Files!=null?c.Files.FirstOrDefault():null):(title=="打开所在目录"?Path.GetDirectoryName(Recognition.LocalPath(detail).TrimEnd(Path.DirectorySeparatorChar)):tag=="应用"||tag=="文件"||title=="直接打开"?detail:null)});}
 void ContentActions(List<Result> rows,ClipEntry c){if(c==null)return;if(c.Files!=null){foreach(string file in c.Files.Take(8)){string p=file;Add(rows,"打开 "+Path.GetFileName(p),p,"文件",()=>Launch(p));Add(rows,"复制文件路径",p,"内容",()=>CopyText(p,false));}return;}if(c.ImagePath!=null){Add(rows,"保存剪贴板图片…","选择 PNG 图片保存位置","图片",SaveCurrentImage);return;}string t=(c.Text??"").Trim();string type=Recognition.TypeOf(t);if(type=="网址")Add(rows,"打开网址",t,"内容",()=>Launch(t));if(type=="路径"){string path=Recognition.LocalPath(t);Add(rows,"直接打开",path,"内容",()=>Launch(path));Add(rows,"打开所在目录",path,"内容",()=>Launch(Path.GetDirectoryName(path.TrimEnd(Path.DirectorySeparatorChar))??path));}if(type=="邮箱")Add(rows,"新建邮件",t,"内容",()=>Launch("mailto:"+t));if(type=="算式"){try{string value=Recognition.Calculate(t);Add(rows,t+" = "+value,"Enter 复制并填入搜索框","计算",()=>CopyText(value,false));}catch{}}if(t.Length>0){Add(rows,"粘贴为纯文本",c.Text,"内容",()=>CopyText(c.Text,true));Add(rows,"复制去除首尾空白后的文本",t,"内容",()=>CopyText(t,false));if(t.Length<4000)Add(rows,"在浏览器搜索这段文字",t,"网页",()=>Launch("https://www.bing.com/search?q="+Uri.EscapeDataString(t)));}}
 void RefreshResults(){if(results==null)return;clearQuery.Visible=query.TextLength>0;refreshingResults=true;string q=query.Text.Trim();var rows=new List<Result>();context.Text=current==null?"复制文字、网址、图片或文件后唤起，这里会显示可用操作。":"已识别："+(current.Text!=null?Recognition.TypeOf(current.Text):current.Kind)+"  ·  "+OneLine(current.Summary);string inputType=Recognition.TypeOf(q);bool inputActions=q.Length>0&&inputType!="文本"&&inputType!="空";if(mode=="全部"||mode=="内容操作"||inputType=="路径"){var actions=new List<Result>();ContentActions(actions,inputActions?new ClipEntry{Text=q}:current);rows.AddRange(actions.Where(x=>inputActions||q.Length==0||Recognition.Matches(x.Title+" "+x.Detail,q)));}if(mode=="全部"||mode=="工具"){if(Recognition.TypeOf(q)=="算式"){try{string value=Recognition.Calculate(q);Add(rows,q+" = "+value,"Enter 复制结果","计算",()=>CopyText(value,false));}catch{}}AddTool(rows,q,"剪贴板历史","选择文本、图片和文件记录",()=>SwitchMode("剪贴板"));AddTool(rows,q,"添加文件搜索目录","将项目或常用目录加入统一搜索",AddFolder);AddTool(rows,q,"刷新搜索索引","扫描开始菜单与已选择的目录",StartIndex);AddTool(rows,q,"清空剪贴板历史","删除本地记录",ClearHistory);}if(mode=="全部"||mode=="应用"||mode=="文件"){foreach(var i in index.Where(i=>(mode=="全部"||(mode=="应用"?i.App:!i.App))&&Recognition.Matches(i.Name+" "+i.Path,q)).OrderByDescending(i=>i.Name.Equals(q,StringComparison.CurrentCultureIgnoreCase)).ThenByDescending(i=>i.App).Take(q.Length==0?30:100)){var item=i;Add(rows,item.Name,item.Path,item.App?"应用":"文件",()=>Launch(item.Path));}}if(mode=="全部"||mode=="剪贴板"){foreach(var c in clips.Where(c=>Recognition.Matches(c.Summary+" "+c.Kind,q)).Take(mode=="全部"?20:100)){var clip=c;Add(rows,clip.ImagePath!=null?"图片 · "+(clip.Created==DateTime.MinValue?"历史记录":clip.Created.ToString("MM-dd HH:mm")):OneLine(clip.Summary),clip.Summary,"剪贴板 · "+clip.Kind,()=>Paste(clip),clip);}}results.BeginUpdate();results.Items.Clear();results.Items.AddRange(rows.ToArray());if(rows.Count>0)results.SelectedIndex=0;results.EndUpdate();refreshingResults=false;ApplyCompactLayout();if(rows.Count==0){previewTitle.Text="暂无结果";previewText.Text="试试其他关键词，或在工具中添加文件搜索目录。";ClearPreviewImage();previewText.Visible=true;}status.Text=(indexing?"正在建立索引…  ":"索引 "+index.Count+" 项  ·  ")+rows.Count+" 个结果  |  ↑↓ 选择  Enter 选用/执行  Ctrl+V 粘贴已选记录  Tab 切换  Esc 关闭";}
 void AddTool(List<Result> rows,string q,string title,string detail,Action action){if(Recognition.Matches(title+" "+detail,q))Add(rows,title,detail,"工具",action);}
 static string OneLine(string text){var s=(text??"").Replace("\r"," ").Replace("\n","  ");return s.Length>160?s.Substring(0,160)+"…":s;}
 void SwitchMode(string value){ChangeMode(value);query.Focus();query.SelectAll();}
 void RemoveChildTag(){string text=query.Text;ChangeMode("全部");query.Text=text;query.Focus();query.SelectionStart=0;query.SelectionLength=0;}
 void DrawResult(object sender,DrawItemEventArgs e){if(e.Index<0)return;Result r=(Result)results.Items[e.Index];bool selected=(e.State&DrawItemState.Selected)!=0;float scale=Math.Max(96,GetDpiForWindow(Handle))/96f;Func<float,int> px=n=>(int)Math.Round(n*scale);using(var canvas=new SolidBrush(results.BackColor))e.Graphics.FillRectangle(canvas,e.Bounds);e.Graphics.SmoothingMode=SmoothingMode.AntiAlias;var card=new Rectangle(e.Bounds.X+px(1),e.Bounds.Y+px(2),e.Bounds.Width-px(4),e.Bounds.Height-px(4));if(selected)using(var path=SoftPanel.Outline(card,px(8)))using(var bg=new SolidBrush(Color.FromArgb(235,237,247)))e.Graphics.FillPath(bg,path);if(DrawThumbnail(e.Graphics,card,r))return;string symbol=r.Clip!=null?r.Clip.Kind.Substring(0,1):r.Tag=="应用"?"应":r.Tag=="文件"?"文":r.Tag=="计算"?"＝":r.Tag=="工具"?"工":"↗";var icon=new Rectangle(card.Left+px(12),card.Top,px(26),card.Height);var nativeIcon=resultIcons.Get(r.IconPath);if(nativeIcon!=null){int size=px(28);e.Graphics.DrawIcon(nativeIcon,new Rectangle(icon.Left+(icon.Width-size)/2,icon.Top+(icon.Height-size)/2,size,size));}else if(r.Tag=="工具"||r.Tag=="计算"){int size=px(26);e.Graphics.DrawIcon(this.Icon,new Rectangle(icon.Left,icon.Top+(icon.Height-size)/2,size,size));}else TextRenderer.DrawText(e.Graphics,symbol,Font,icon,muted,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter);var title=new Rectangle(card.Left+px(50),card.Top,card.Width-px(135),card.Height);TextRenderer.DrawText(e.Graphics,r.Title,Font,title,ink,TextFormatFlags.EndEllipsis|TextFormatFlags.SingleLine|TextFormatFlags.VerticalCenter|TextFormatFlags.NoPadding);var tag=new Rectangle(card.Right-px(72),card.Top,px(60),card.Height);using(var font=new Font(Font.FontFamily,Font.Size*.82f))TextRenderer.DrawText(e.Graphics,selectedForManualPaste&&selected&&r.Clip!=null?"已选用":r.Clip!=null?r.Clip.Kind:r.Tag,font,tag,muted,TextFormatFlags.Right|TextFormatFlags.VerticalCenter|TextFormatFlags.SingleLine);}
 void ClearPreviewImage(){if(previewImage.Image!=null){previewImage.Image.Dispose();previewImage.Image=null;}previewImage.Visible=false;}
 void UpdatePreview(){var r=results.SelectedItem as Result;if(r==null)return;ClearPreviewImage();previewTitle.Text=r.Tag;previewAction.Text=r.Clip!=null?"选用":"打开";previewText.Visible=true;previewText.Text=r.Detail??"";if(r.Clip!=null&&r.Clip.ImagePath!=null)try{using(var img=Image.FromFile(r.Clip.ImagePath))previewImage.Image=new Bitmap(img);previewImage.Visible=true;previewText.Visible=false;}catch{previewText.Text="图片文件不可用";}}
 void Execute(bool copyOnly){var r=results.SelectedItem as Result;if(r==null)return;try{if(r.Clip!=null)Paste(r.Clip);else r.Run();}catch(Exception ex){ignoreClip=false;modal=true;MessageBox.Show(this,ex.Message,"无法完成操作");modal=false;}}
 void ActivateClickedResult(Point point,MouseButtons button){if(button!=MouseButtons.Left)return;int index=results.IndexFromPoint(point);if(index<0||index>=results.Items.Count||!results.GetItemRectangle(index).Contains(point))return;results.SelectedIndex=index;Execute(false);}
 void Launch(string path){Hide();Process.Start(new ProcessStartInfo(path){UseShellExecute=true});}
 void PutClipboard(ClipEntry c){ignoreClip=true;if(c.Files!=null){var files=new StringCollection();files.AddRange(c.Files);Clipboard.SetFileDropList(files);}else if(c.ImagePath!=null){using(var img=Image.FromFile(c.ImagePath))Clipboard.SetImage(img);}else Clipboard.SetText(c.Text??"");}
 void Paste(ClipEntry c){PutClipboard(c);clipboardRelease.Stop();clipboardRelease.Start();current=c;pendingClipboardQuery=false;selectedForManualPaste=true;clips.Remove(c);clips.Insert(0,c);Save();RefreshResults();int pos=results.Items.Cast<Result>().ToList().FindIndex(r=>r.Clip==c);if(pos>=0)results.SelectedIndex=pos;status.Text="已选用并置顶；按 Ctrl+V 返回原窗口粘贴，或 Esc 关闭后手动粘贴。";}
 void CopyText(string text,bool paste){ignoreClip=true;Clipboard.SetText(text);clipboardRelease.Stop();clipboardRelease.Start();if(paste)ReturnAndPaste();else{current=new ClipEntry{Text=text,Created=DateTime.Now};clips.RemoveAll(c=>c.Text==text);clips.Insert(0,current);Save();query.Text=text;RefreshResults();query.SelectAll();status.Text="结果已复制并填入搜索框。";}}
 protected override bool ProcessCmdKey(ref Message msg,Keys keyData){Keys key=keyData&Keys.KeyCode;bool shift=(keyData&Keys.Shift)!=0;bool ctrl=(keyData&Keys.Control)!=0;bool tabFocused=tabs.Controls.Cast<Control>().Any(c=>c.Focused);bool inPreview=preview.ContainsFocus;bool inQuery=query.Focused;
  if((keyData&Keys.Alt)!=0&&(key==Keys.Left||key==Keys.Right)){int i=Array.IndexOf(modes,mode);ChangeMode(modes[(i+(key==Keys.Left?modes.Length-1:1))%modes.Length]);query.Focus();return true;}
  if(key==Keys.V&&ctrl&&selectedForManualPaste){selectedForManualPaste=false;ReturnAndPaste();return true;}
  if(key==Keys.Escape){RememberSearch();Hide();return true;}
  if(key==Keys.Tab){int n=Array.IndexOf(modes,mode);ChangeMode(modes[(n+(shift?5:1))%modes.Length]);query.Focus();return true;}
  if((key==Keys.Left||key==Keys.Right)&&!ctrl){bool atEdge=inQuery&&(query.TextLength==0||query.SelectionLength==query.TextLength||(query.SelectionLength==0&&(key==Keys.Left?query.SelectionStart==0:query.SelectionStart==query.TextLength)));if(tabFocused||atEdge){int n=Array.IndexOf(modes,mode);ChangeMode(modes[(n+(key==Keys.Left?modes.Length-1:1))%modes.Length]);if(tabFocused)((Button)tabs.Controls[Array.IndexOf(modes,mode)]).Focus();else query.Focus();return true;}if(results.Focused){query.Focus();return true;}if(inPreview&&key==Keys.Left){results.Focus();return true;}if(childTag.Focused&&key==Keys.Right){query.Focus();return true;}}
  if(key==Keys.Up||key==Keys.Down){if(inQuery){if(key==Keys.Up)((Button)tabs.Controls[Array.IndexOf(modes,mode)]).Focus();else{previewRequested=true;ApplyCompactLayout();results.Focus();if(results.Items.Count>0&&results.SelectedIndex<0)results.SelectedIndex=0;}return true;}if(tabFocused||childTag.Focused){if(key==Keys.Up)query.Focus();else{previewRequested=true;ApplyCompactLayout();results.Focus();}return true;}if(results.Focused){int n=results.SelectedIndex+(key==Keys.Down?1:-1);if(n<0)query.Focus();else if(n<results.Items.Count)results.SelectedIndex=n;return true;}if(inPreview){if(key==Keys.Up)query.Focus();else{previewRequested=true;ApplyCompactLayout();results.Focus();}return true;}}
  if(key==Keys.Enter){if(clearQuery.Focused){clearQuery.PerformClick();return true;}if(childTag.Focused){RemoveChildTag();return true;}if(tabFocused){query.Focus();return true;}Execute(ctrl);return true;}
  if((key==Keys.Delete||key==Keys.Back)&&childTag.Focused){RemoveChildTag();return true;}
  if(key==Keys.Back&&!ctrl&&!shift&&inQuery&&query.SelectionStart==0&&query.SelectionLength==0&&mode!="全部"){RemoveChildTag();return true;}
  if(key==Keys.Delete&&results.Focused){var r=results.SelectedItem as Result;if(r!=null&&r.Clip!=null){ClearPreviewImage();clips.Remove(r.Clip);DeleteImage(r.Clip);Save();RefreshResults();}return true;}
  return base.ProcessCmdKey(ref msg,keyData);
 }
 void ReturnAndPaste(){Hide();pastePending=previous!=IntPtr.Zero&&previous!=Handle;if(pastePending)SetForegroundWindow(previous);pasteTimer.Start();}
 void SaveCurrentImage(){modal=true;try{using(var dialog=new SaveFileDialog{Filter="PNG 图片|*.png",FileName="剪贴板图片.png"})if(dialog.ShowDialog(this)==DialogResult.OK)using(var img=Clipboard.GetImage()){if(img==null)throw new Exception("当前剪贴板已不是图片，请重新复制。");img.Save(dialog.FileName,System.Drawing.Imaging.ImageFormat.Png);status.Text="图片已保存。";}}finally{modal=false;}}
 protected override void Dispose(bool disposing){if(disposing){UnregisterHotKey(Handle,1);UnregisterHotKey(Handle,2);RemoveClipboardFormatListener(Handle);ClearPreviewImage();if(tray!=null)tray.Dispose();if(brandMark.Image!=null)brandMark.Image.Dispose();resultIcons.Dispose();foreach(var image in thumbnails.Values)image.Dispose();thumbnails.Clear();clipboardRelease.Dispose();pasteTimer.Dispose();}base.Dispose(disposing);}
 [STAThread] public static void Main(string[] args){bool created;using(var mutex=new System.Threading.Mutex(true,"Local\\LilyToolsLauncher",out created)){if(!created)return;Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);Application.Run(new Launcher());}}
